}'","description":"Find files larger than 100MB","timeout":180000}

{"command":"echo '=== inspect neo4j ==='
docker inspect neo4j --format 'Status={{.State.Status}} Restart={{.HostConfig.RestartPolicy.Name}} Image={{.Config.Image}}
Ports={{json .HostConfig.PortBindings}}
Binds={{json .HostConfig.Binds}}
Labels compose.project={{index .Config.Labels "com.docker.compose.project"}} compose.file={{index .Config.Labels "com.docker.compose.project.config_files"}} compose.workdir={{index .Config.Labels "com.docker.compose.project.working_dir"}} compose.service={{index .Config.Labels "com.docker.compose.service"}}
Cmd={{json .Config.Cmd}}
Env related: '
docker inspect neo4j --format '{{range .Config.Env}}{{println .}}{{end}}' | grep -Ei 'NEO4J|BOLT|HTTP|HOST|LISTEN' || true
echo
echo '=== compose labels raw ==='
docker inspect neo4j --format '{{json .Config.Labels}}' | python3 -c 'import json,sys; d=json.load(sys.stdin); [print(k,"=",v) for k,v in sorted(d.items()) if "compose" in k.lower() or "project" in k.lower()]'","description":"Inspect Neo4j container ports and compose labels"}
